// ---- content/count.js ----
// Тема «Правила подсчёта, перестановки, сочетания» (7–9 класс + олимпиадный уровень).
// Правила суммы и произведения, перестановки и размещения, сочетания, треугольник Паскаля и пути на сетке,
// перестановки с повторениями, олимпиадные приёмы: дополнение, симметрия, рекурсия.
(function () {
  function fr(a, b) { return '<span class="fr"><span>' + a + '</span><span>' + b + '</span></span>'; }
  // C из n по k и A из n по k: индексы друг над другом, как в учебниках
  function C(n, k) { return 'C<span class="ix"><span>' + k + '</span><span>' + n + '</span></span>'; }
  function A(n, k) { return 'A<span class="ix"><span>' + k + '</span><span>' + n + '</span></span>'; }

  // пути на сетке 4 × 2: сетка пунктиром, один путь выделен
  var gp = {}, gl = [], gh = [];
  for (var i = 0; i <= 4; i++) for (var j = 0; j <= 2; j++) { gp['g' + i + j] = [i, j]; gh.push('g' + i + j); }
  for (var r = 0; r <= 2; r++) gl.push(['g0' + r, 'g4' + r]);
  for (var c = 0; c <= 4; c++) gl.push(['g' + c + '0', 'g' + c + '2']);
  gp.A = [0, 0]; gp.B = [4, 2];
  var figGrid = MM.fig({
    pts: gp, dash: gl, hide: gh,
    gold: [['A', 'g10'], ['g10', 'g11'], ['g11', 'g31'], ['g31', 'g32'], ['g32', 'B']],
    lab: { A: 'sw', B: 'ne' },
    w: 220, alt: 'Сетка 4 на 2 клетки. Выделен путь из левого нижнего угла A в правый верхний угол B: вправо, вверх, вправо, вправо, вверх, вправо'
  });

  MM.addTopic({
    id: 'count',
    sec: 'comb',
    title: 'Правила подсчёта, перестановки, сочетания',
    blurb: `Как считать варианты, не перебирая их: правила суммы и произведения, перестановки, сочетания, треугольник Паскаля и олимпиадные приёмы. Без этого не решаются задачи на подсчёт и вероятность.`,

    lessons: [
      { id: 'cnt-l1', title: 'Правила суммы и произведения', mins: 12, html: `
<p>Комбинаторика отвечает на вопрос «сколькими способами?». Почти все её формулы выводятся из двух простых правил.</p>
<div class="box"><div class="box-h">Два правила</div><ul>
<li><b>Правило суммы.</b> Если предмет можно выбрать из одной группы <span class="m">m</span> способами, а из другой — <span class="m">n</span> способами, и группы не пересекаются, то выбрать один предмет можно <span class="m">m + n</span> способами.</li>
<li><b>Правило произведения.</b> Если выбор делается в два шага, на первом шаге <span class="m">m</span> вариантов, а на втором — <span class="m">n</span> вариантов <b>при любом</b> выборе на первом шаге, то всего <span class="m">m · n</span> вариантов.</li>
</ul></div>
<p>Правило произведения работает для любого числа шагов. Сколько трёхзначных чисел делятся на 5? Первая цифра — 9 вариантов (от 1 до 9), вторая — 10, последняя — 2 (0 или 5). Всего <span class="m">9 · 10 · 2 = 180</span>.</p>
<div class="ex"><div class="ex-h">Пример 1</div>
<p>Сколько существует четырёхзначных чисел, у которых все цифры различны?</p>
<p><b>Решение.</b> Первая цифра — любая, кроме нуля: 9 вариантов. Вторая — любая, кроме первой: тоже 9 (ноль теперь можно). Третья — 8 вариантов, четвёртая — 7. Всего <span class="m">9 · 9 · 8 · 7 = 4536</span>.</p></div>
<h3>Когда число вариантов зависит от прошлого выбора</h3>
<p>Правило произведения требует, чтобы на каждом шаге число вариантов было одним и тем же при любых прошлых выборах. Если это не так, разбей задачу на случаи и сложи результаты.</p>
<div class="ex"><div class="ex-h">Пример 2</div>
<p>Сколько существует чётных трёхзначных чисел с различными цифрами?</p>
<p><b>Решение.</b> Число вариантов для первой цифры зависит от того, равна ли нулю последняя. Разберём два случая.</p>
<ul>
<li>Последняя цифра 0. Первая — любая из 9 ненулевых, средняя — 8 вариантов: <span class="m">9 · 8 = 72</span>.</li>
<li>Последняя цифра 2, 4, 6 или 8 (4 варианта). Первая — не 0 и не последняя: 8 вариантов. Средняя — 8 вариантов: <span class="m">4 · 8 · 8 = 256</span>.</li>
</ul>
<p>Ответ: <span class="m">72 + 256 = 328</span>.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Начинай выбор с самого «стеснённого» места: с первой цифры, которая не может быть нулём, или с позиции, на которую наложено условие. Если число вариантов на шаге зависит от прошлых шагов — разбей на случаи по этому шагу.</p></div>` },

      { id: 'cnt-l2', title: 'Перестановки и размещения', mins: 12, html: `
<p><b>Перестановка</b> — это расстановка <span class="m">n</span> разных предметов в ряд. Первый предмет выбираем <span class="m">n</span> способами, второй — <span class="m">n − 1</span>, …, последний — одним. Поэтому число перестановок равно</p>
<p class="calc"><span class="m">n! = 1 · 2 · 3 · … · n</span> (читается «эн факториал»).</p>
<p>Первые значения стоит помнить: <span class="m">3! = 6</span>, <span class="m">4! = 24</span>, <span class="m">5! = 120</span>, <span class="m">6! = 720</span>, <span class="m">7! = 5040</span>. По определению <span class="m">0! = 1</span>.</p>
<p><b>Размещение</b> из <span class="m">n</span> по <span class="m">k</span> — это упорядоченный выбор <span class="m">k</span> предметов из <span class="m">n</span>. Их число</p>
<p class="calc"><span class="m">${A('n', 'k')} = n(n − 1) … (n − k + 1) = ${fr('n!', '(n − k)!')}</span>.</p>
<p>Например, золото, серебро и бронзу среди 7 бегунов можно распределить <span class="m">${A('7', '3')} = 7 · 6 · 5 = 210</span> способами.</p>
<h3>Приём «склейка»</h3>
<div class="ex"><div class="ex-h">Пример</div>
<p>Сколькими способами можно поставить на полку 7 разных книг так, чтобы 3 книги по математике стояли рядом?</p>
<p><b>Решение.</b> Склеим три книги по математике в один блок. Теперь нужно расставить 5 предметов: <span class="m">5! = 120</span> способов. Внутри блока книги можно переставить <span class="m">3! = 6</span> способами. Всего <span class="m">120 · 6 = 720</span>.</p></div>
<h3>Круглый стол</h3>
<p>Пусть рассадки за круглым столом, отличающиеся только поворотом, считаются одинаковыми. Рассадок на занумерованные стулья <span class="m">n!</span>, и каждую «круговую» рассадку мы при этом посчитали <span class="m">n</span> раз — по числу поворотов. Поэтому круговых рассадок <span class="m">${fr('n!', 'n')} = (n − 1)!</span>. Например, пять человек за круглым столом: <span class="m">4! = 24</span> рассадки.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Если в твоём подсчёте каждый нужный объект встретился одно и то же число раз, раздели на это число. Так получаются формулы для круглого стола, для сочетаний и для разбиения на группы.</p></div>` },

      { id: 'cnt-l3', title: 'Сочетания', mins: 14, html: `
<p><b>Сочетание</b> из <span class="m">n</span> по <span class="m">k</span> — это выбор <span class="m">k</span> предметов из <span class="m">n</span>, когда порядок не важен, то есть подмножество из <span class="m">k</span> элементов. Число сочетаний обозначают <span class="m">${C('n', 'k')}</span> (читается «цэ из эн по ка»); в других книгах пишут <span class="m">C(n, k)</span>.</p>
<p>Упорядоченных выборов <span class="m">${A('n', 'k')}</span>. Каждое подмножество из <span class="m">k</span> элементов встречается среди них <span class="m">k!</span> раз — по числу способов упорядочить его элементы. Поэтому</p>
<p class="calc"><span class="m">${C('n', 'k')} = ${fr(A('n', 'k'), 'k!')} = ${fr('n!', 'k! (n − k)!')}</span>.</p>
<div class="box"><div class="box-h">Запомни</div><ul>
<li><span class="m">${C('n', '0')} = ${C('n', 'n')} = 1</span>, <span class="m">${C('n', '1')} = n</span>, <span class="m">${C('n', '2')} = ${fr('n(n − 1)', '2')}</span>.</li>
<li><span class="m">${C('n', 'k')} = ${C('n', 'n − k')}</span>: выбрать <span class="m">k</span> предметов — то же, что выбрать <span class="m">n − k</span> оставшихся.</li>
<li>Порядок важен — размещения. Порядок не важен — сочетания.</li>
</ul></div>
<div class="ex"><div class="ex-h">Пример 1</div>
<p>Сколькими способами из 10 учеников можно выбрать команду из 4 человек?</p>
<p><b>Решение.</b> <span class="m">${C('10', '4')} = ${fr('10 · 9 · 8 · 7', '4 · 3 · 2 · 1')} = 210</span>.</p></div>
<div class="ex"><div class="ex-h">Пример 2</div>
<p>В кружке 5 мальчиков и 7 девочек. Сколькими способами можно выбрать 2 мальчиков и 3 девочек?</p>
<p><b>Решение.</b> Мальчиков выбираем <span class="m">${C('5', '2')} = 10</span> способами, девочек — <span class="m">${C('7', '3')} = 35</span> способами. Выборы независимы, поэтому всего <span class="m">10 · 35 = 350</span>.</p></div>
<h3>Сочетания в геометрии</h3>
<p>Отрезков с концами в <span class="m">n</span> точках — <span class="m">${C('n', '2')}</span>. Если никакие три точки не лежат на одной прямой, треугольников с вершинами в этих точках — <span class="m">${C('n', '3')}</span>. У выпуклого <span class="m">n</span>-угольника <span class="m">${C('n', '2')} − n = ${fr('n(n − 3)', '2')}</span> диагоналей: из всех отрезков убираем стороны.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Удобно считать <span class="m">${C('n', 'k')}</span> так: в числителе <span class="m">k</span> множителей от <span class="m">n</span> вниз, в знаменателе <span class="m">k!</span>. Например, <span class="m">${C('12', '3')} = ${fr('12 · 11 · 10', '6')} = 220</span>. Если <span class="m">k</span> больше половины <span class="m">n</span>, сначала замени <span class="m">k</span> на <span class="m">n − k</span>.</p></div>` },

      { id: 'cnt-l4', title: 'Треугольник Паскаля и пути на сетке', mins: 14, html: `
<div class="box"><div class="box-h">Правило Паскаля</div>
<p class="calc"><span class="m">${C('n', 'k')} = ${C('n − 1', 'k − 1')} + ${C('n − 1', 'k')}</span>.</p></div>
<p><b>Доказательство без формул.</b> Выбираем <span class="m">k</span> человек из <span class="m">n</span>. Посмотрим на одного из них — Аню. Если Аня выбрана, остальных <span class="m">k − 1</span> выбираем из <span class="m">n − 1</span>: <span class="m">${C('n − 1', 'k − 1')}</span> способов. Если не выбрана — всех <span class="m">k</span> выбираем из <span class="m">n − 1</span> остальных: <span class="m">${C('n − 1', 'k')}</span> способов. Вместе это все выборы.</p>
<p>По этому правилу числа <span class="m">${C('n', 'k')}</span> выписывают треугольником: каждое число равно сумме двух чисел над ним. Строки с номерами от 0 до 6:</p>
<p class="calc" style="text-align:center">1<br>1 1<br>1 2 1<br>1 3 3 1<br>1 4 6 4 1<br>1 5 10 10 5 1<br>1 6 15 20 15 6 1</p>
<p>Сумма чисел в строке с номером <span class="m">n</span> равна <span class="m">2<sup>n</sup></span>: это число всех подмножеств множества из <span class="m">n</span> элементов (каждый элемент либо берём, либо нет).</p>
<h3>Пути на клетчатой сетке</h3>
<p>Сколькими путями можно пройти из <span class="m">A</span> в <span class="m">B</span> по линиям сетки 4 × 2, двигаясь только вправо и вверх?</p>
${figGrid}
<p>Любой такой путь состоит из 6 шагов: 4 шагов вправо и 2 шагов вверх. Путь однозначно задаётся тем, какие 2 из 6 шагов идут вверх. Значит, путей <span class="m">${C('6', '2')} = 15</span>. В общем случае из угла в угол прямоугольника <span class="m">m × n</span> клеток ведут <span class="m">${C('m + n', 'n')}</span> путей.</p>
<p>Связь с треугольником Паскаля: в каждую точку сетки приходят либо слева, либо снизу. Поэтому число путей до точки равно сумме чисел путей до двух соседних точек — это и есть правило Паскаля.</p>
<h3>Тождества без вычислений</h3>
<p>Тождество можно доказать, посчитав одно и то же двумя способами. Докажем <span class="m">k · ${C('n', 'k')} = n · ${C('n − 1', 'k − 1')}</span>. Сколькими способами из <span class="m">n</span> человек можно выбрать команду из <span class="m">k</span> человек и капитана в ней? Можно сначала выбрать команду (<span class="m">${C('n', 'k')}</span>), потом капитана в ней (<span class="m">k</span>) — получаем левую часть. А можно сначала капитана (<span class="m">n</span>), потом остальных <span class="m">k − 1</span> из <span class="m">n − 1</span> — правую часть.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Прежде чем доказывать тождество с <span class="m">${C('n', 'k')}</span> выкладками, спроси себя: что считает левая часть, а что — правая? Часто доказательство умещается в две строки.</p></div>` },

      { id: 'cnt-l5', title: 'Перестановки с повторениями и разбиения на группы', mins: 14, html: `
<p>Сколько разных «слов» можно получить, переставляя буквы слова МАТЕМАТИКА? Букв 10, но среди них есть одинаковые: М — 2 раза, А — 3 раза, Т — 2 раза, Е, И, К — по одному. Если бы все буквы были разными, перестановок было бы <span class="m">10!</span>. Каждое слово в этом подсчёте встречается <span class="m">2! · 3! · 2! = 24</span> раза — столько способов переставить одинаковые буквы между собой. Поэтому слов</p>
<p class="calc"><span class="m">${fr('10!', '2! · 3! · 2!')} = 151200</span>.</p>
<div class="box"><div class="box-h">Формула</div>
<p>Если среди <span class="m">n</span> предметов <span class="m">n<sub>1</sub></span> одинаковых первого вида, <span class="m">n<sub>2</sub></span> одинаковых второго вида, …, <span class="m">n<sub>k</sub></span> одинаковых <span class="m">k</span>-го вида, то различных расстановок в ряд</p>
<p class="calc"><span class="m">${fr('n!', 'n<sub>1</sub>! n<sub>2</sub>! … n<sub>k</sub>!')}</span>.</p></div>
<p>Частный случай: строк длины <span class="m">n</span> из <span class="m">k</span> единиц и <span class="m">n − k</span> нулей ровно <span class="m">${fr('n!', 'k! (n − k)!')} = ${C('n', 'k')}</span>. Строки из нулей и единиц, пути на сетке и подмножества — одно и то же, записанное по-разному.</p>
<h3>Разбиения на группы</h3>
<div class="ex"><div class="ex-h">Пример</div>
<p>Сколькими способами 9 учеников можно разбить на три группы по 3 человека, если: а) группы едут в три разных города; б) группы ничем не отличаются?</p>
<p><b>Решение.</b> а) Группу для первого города выбираем <span class="m">${C('9', '3')} = 84</span> способами, для второго — <span class="m">${C('6', '3')} = 20</span>, оставшиеся едут в третий: <span class="m">84 · 20 = 1680</span>. б) Теперь каждое разбиение посчитано <span class="m">3! = 6</span> раз — по числу способов назначить три группы трём городам. Ответ: <span class="m">1680 : 6 = 280</span>.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Главная ловушка — путаница «различимые или нет». Перед подсчётом ответь на три вопроса. Различаются ли предметы? Различаются ли группы (ящики, места)? Важен ли порядок внутри группы? Если группы одинаковые, а ты считал их разными, раздели на число их перестановок.</p></div>` },

      { id: 'cnt-l6', title: 'Олимпиадные приёмы подсчёта', mins: 16, html: `
<h3>1. Дополнение</h3>
<p>Иногда проще посчитать то, что <b>не</b> подходит, и вычесть из общего числа.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>Сколько существует пятизначных чисел, в записи которых есть хотя бы две одинаковые цифры?</p>
<p><b>Решение.</b> Всего пятизначных чисел 90000. Чисел с различными цифрами <span class="m">9 · 9 · 8 · 7 · 6 = 27216</span>. Ответ: <span class="m">90000 − 27216 = 62784</span>.</p></div>
<h3>2. Включения и исключения</h3>
<p>Для двух множеств <span class="m">|A ∪ B| = |A| + |B| − |A ∩ B|</span>: общие элементы посчитаны дважды, и один раз их вычитаем. Например, чисел от 1 до 100, делящихся на 2 или на 5: <span class="m">50 + 20 − 10 = 60</span>. Для трёх множеств:</p>
<p class="calc"><span class="m">|A ∪ B ∪ C| = |A| + |B| + |C| − |A ∩ B| − |B ∩ C| − |C ∩ A| + |A ∩ B ∩ C|</span>.</p>
<h3>3. Симметрия</h3>
<p>В скольких перестановках чисел 1, 2, …, 6 число 1 стоит левее числа 2? Поменяв местами 1 и 2, получим перестановку, где 1 стоит правее. Все перестановки разбиваются на такие пары, поэтому ответ — ровно половина: <span class="m">720 : 2 = 360</span>.</p>
<h3>4. Рекуррентное соотношение</h3>
<p>Сколькими способами можно замостить полоску 2 × <span class="m">n</span> доминошками 1 × 2? Обозначим ответ <span class="m">a<sub>n</sub></span>. Посмотрим на левый край. Либо там стоит вертикальная доминошка, и остаётся полоска 2 × <span class="m">(n − 1)</span>. Либо там две горизонтальные доминошки одна над другой, и остаётся 2 × <span class="m">(n − 2)</span>. Поэтому</p>
<p class="calc"><span class="m">a<sub>n</sub> = a<sub>n−1</sub> + a<sub>n−2</sub></span>, <span class="m">a<sub>1</sub> = 1</span>, <span class="m">a<sub>2</sub> = 2</span>,</p>
<p>и дальше 3, 5, 8, … Для полоски 2 × 5 получается 8 способов.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Если прямой подсчёт запутан: 1) посчитай дополнение; 2) найди симметрию, которая делит объекты на равные части; 3) посмотри на первый или последний шаг и получи рекуррентное соотношение; 4) проверь ответ на маленьких случаях — их можно перебрать вручную.</p></div>` }
    ],

    problems: [
      // ── Уровень 1 · База ──
      { id: 'cnt-01', lvl: 1, r: 800, type: 'num', q: `В школьной столовой 4 вида супа и 6 видов второго блюда. Сколькими способами можно выбрать обед из одного супа и одного второго блюда?`, a: ['24'],
        hints: [`Правило произведения.`],
        sol: `Суп выбираем 4 способами, второе — 6 способами при любом супе: 4 · 6 = 24.` },
      { id: 'cnt-02', lvl: 1, r: 830, type: 'num', q: `Сколько существует трёхзначных чисел, все цифры которых нечётные?`, a: ['125'],
        hints: [`Нечётных цифр пять: 1, 3, 5, 7, 9. Нуля среди них нет, так что с первой цифрой проблем не будет.`],
        sol: `Каждую из трёх цифр выбираем 5 способами: 5 · 5 · 5 = 125.` },
      { id: 'cnt-03', lvl: 1, r: 860, type: 'num', q: `Сколькими способами можно поставить на полку в ряд 5 разных книг?`, a: ['120'],
        hints: [`На первое место — 5 вариантов, на второе — 4, …`],
        sol: `5! = 5 · 4 · 3 · 2 · 1 = 120.` },
      { id: 'cnt-04', lvl: 1, r: 890, type: 'num', q: `Сколько существует трёхзначных чисел, у которых все цифры различны?`, a: ['648'],
        hints: [`Первая цифра не может быть нулём.`, `9 вариантов для первой цифры, 9 — для второй, 8 — для третьей.`],
        sol: `Первая цифра — от 1 до 9 (9 вариантов), вторая — любая, кроме первой (9 вариантов, ноль можно), третья — 8 вариантов. 9 · 9 · 8 = 648.` },
      { id: 'cnt-05', lvl: 1, r: 920, type: 'num', q: `В классе 20 учеников. Сколькими способами можно выбрать старосту и его заместителя?`, a: ['380'],
        hints: [`Порядок важен: староста и заместитель — разные должности.`],
        sol: `Старосту выбираем 20 способами, заместителя — из оставшихся 19: 20 · 19 = 380.` },
      { id: 'cnt-06', lvl: 1, r: 960, type: 'num', q: `В турнире 8 шахматистов, каждый сыграл с каждым ровно одну партию. Сколько всего партий было сыграно?`, a: ['28'],
        hints: [`Партия — это пара игроков, порядок в паре не важен.`, `Каждый сыграл 7 партий, но при подсчёте 8 · 7 каждая партия учтена дважды.`],
        sol: `Партий столько же, сколько пар игроков: ${C('8', '2')} = ${fr('8 · 7', '2')} = 28.` },
      { id: 'cnt-07', lvl: 1, r: 1000, type: 'num', q: `Сколько существует пятизначных чисел, которые читаются одинаково слева направо и справа налево (например, 12321)?`, a: ['900'],
        hints: [`Такое число определяется первыми тремя цифрами.`],
        sol: `Четвёртая цифра равна второй, пятая — первой. Первая цифра — 9 вариантов, вторая и третья — по 10: 9 · 10 · 10 = 900.` },
      { id: 'cnt-08', lvl: 1, r: 1040, type: 'choice', q: `Чего больше: способов выбрать 3 человек из 10 или способов выбрать 7 человек из 10?`, opts: ['способов выбрать 3 человек', 'способов выбрать 7 человек', 'поровну', 'зависит от того, кого выбирают'], a: 2,
        hints: [`Выбрать 7 человек — то же самое, что выбрать 3, которых не возьмём.`],
        sol: `Каждому выбору семерых соответствует ровно один выбор троих — тех, кто остался. Поэтому способов поровну: ${C('10', '3')} = ${C('10', '7')} = 120.` },

      // ── Уровень 2 · Районный этап ──
      { id: 'cnt-09', lvl: 2, r: 1070, type: 'num', q: `Сколькими способами можно разложить 4 разных письма по 3 почтовым ящикам? В один ящик можно положить несколько писем, ящики могут остаться пустыми.`, a: ['81'],
        hints: [`Для каждого письма выбираем ящик.`],
        sol: `Каждое из 4 писем кладём в любой из 3 ящиков: 3 · 3 · 3 · 3 = 3<sup>4</sup> = 81. Частая ошибка — ответ 4<sup>3</sup>: так было бы, если бы каждый ящик выбирал одно письмо.` },
      { id: 'cnt-10', lvl: 2, r: 1100, type: 'num', q: `Сколько диагоналей у выпуклого 12-угольника?`, a: ['54'],
        hints: [`Из каждой вершины выходят диагонали ко всем вершинам, кроме неё самой и двух соседних.`],
        sol: `Из каждой вершины выходят 12 − 3 = 9 диагоналей. 12 · 9 = 108, но так каждая диагональ посчитана дважды (с двух концов): 108 : 2 = 54.` },
      { id: 'cnt-11', lvl: 2, r: 1130, type: 'num', q: `Сколько разных «слов» (не обязательно осмысленных) можно получить, переставляя буквы слова ЗАДАЧА?`, a: ['120'],
        hints: [`В слове 6 букв, из них три буквы А.`, `6! нужно разделить на число перестановок одинаковых букв.`],
        sol: `${fr('6!', '3!')} = ${fr('720', '6')} = 120.` },
      { id: 'cnt-12', lvl: 2, r: 1160, type: 'num', q: `В классе 30 учеников. 18 из них ходят в шахматный кружок, 15 — в математический, а 5 не ходят ни в один из этих кружков. Сколько учеников ходят в оба кружка?`, a: ['8'],
        hints: [`Хотя бы в один кружок ходят 30 − 5 = 25 учеников.`, `|A ∪ B| = |A| + |B| − |A ∩ B|.`],
        sol: `Хотя бы в один кружок ходят 25 человек. В сумме 18 + 15 = 33 те, кто ходит в оба кружка, посчитаны дважды. Поэтому в оба ходят 33 − 25 = 8 человек.` },
      { id: 'cnt-13', lvl: 2, r: 1190, type: 'num', q: `Сколько подмножеств у множества из 10 элементов (считая пустое множество и само множество)?`, a: ['1024'],
        hints: [`Каждый элемент либо входит в подмножество, либо нет.`],
        sol: `Для каждого из 10 элементов два варианта: 2<sup>10</sup> = 1024.` },
      { id: 'cnt-14', lvl: 2, r: 1220, type: 'num', q: `Сколькими способами 6 человек могут сесть в ряд на 6 стульев так, чтобы Аня и Боря сидели рядом?`, a: ['240'],
        hints: [`«Склей» Аню и Борю в один блок.`, `Блок и ещё 4 человека — 5 объектов; внутри блока 2 порядка.`],
        sol: `Блок «Аня + Боря» и ещё 4 человека расставляем 5! = 120 способами, внутри блока 2 порядка: 120 · 2 = 240.` },
      { id: 'cnt-15', lvl: 2, r: 1250, type: 'num', q: `Сколько существует четырёхзначных чисел, в записи которых есть хотя бы одна цифра 7?`, a: ['3168'],
        hints: [`Посчитай числа, в которых семёрки нет вовсе.`, `Без семёрки: первая цифра — 8 вариантов, остальные — по 9.`],
        sol: `Всего четырёхзначных чисел 9000. Без цифры 7: 8 · 9 · 9 · 9 = 5832. Ответ: 9000 − 5832 = 3168.` },
      { id: 'cnt-16', lvl: 2, r: 1280, type: 'num', q: `Двигаясь только вправо или вверх по линиям клетчатой сетки, нужно пройти из левого нижнего угла прямоугольника 5 × 3 клетки в правый верхний. Сколько существует таких путей?`, a: ['56'],
        hints: [`Каждый путь состоит из 5 шагов вправо и 3 шагов вверх.`, `Путь определяется тем, какие 3 из 8 шагов идут вверх.`],
        sol: `${C('8', '3')} = ${fr('8 · 7 · 6', '6')} = 56.` },
      { id: 'cnt-17', lvl: 2, r: 1310, type: 'num', q: `Сколькими способами 7 человек могут сесть за круглый стол? Рассадки, отличающиеся только поворотом стола, считаются одинаковыми.`, a: ['720'],
        hints: [`Посади одного человека на любое место — от поворота это не зависит.`],
        sol: `Посадим Аню. Рассадка определяется тем, в каком порядке остальные 6 человек сидят по часовой стрелке от неё: 6! = 720. Иначе: 7! рассадок на занумерованные стулья, и каждая круговая рассадка посчитана 7 раз: 5040 : 7 = 720.` },
      { id: 'cnt-18', lvl: 2, r: 1340, type: 'num', q: `Сколькими способами можно поставить на шахматную доску 8 × 8 белую и чёрную ладьи так, чтобы они не били друг друга?`, a: ['3136'],
        hints: [`Белую ладью можно поставить на любую из 64 клеток.`, `Чёрная не должна стоять ни на той же горизонтали, ни на той же вертикали.`],
        sol: `Белую ставим 64 способами. Её горизонталь и вертикаль вместе занимают 15 клеток (включая её собственную), для чёрной остаётся 64 − 15 = 49 клеток. 64 · 49 = 3136.` },

      // ── Уровень 3 · Полуфинал ──
      { id: 'cnt-19', lvl: 3, r: 1370, type: 'num', q: `В кружке 6 мальчиков и 4 девочки. Сколькими способами можно выбрать команду из 3 человек, в которой есть хотя бы одна девочка?`, a: ['100'],
        hints: [`Посчитай команды без девочек и вычти.`],
        sol: `Всего команд ${C('10', '3')} = 120, из одних мальчиков ${C('6', '3')} = 20. Ответ: 120 − 20 = 100. Частая ошибка: «выберем одну девочку (4 способа), потом любых двоих из оставшихся 9 (36 способов)» — получается 144, потому что команды с несколькими девочками посчитаны несколько раз.` },
      { id: 'cnt-20', lvl: 3, r: 1400, type: 'num', q: `Сколько прямоугольников (включая квадраты), составленных из клеток, есть на шахматной доске 8 × 8?`, a: ['1296'],
        hints: [`Прямоугольник определяется двумя вертикальными и двумя горизонтальными линиями сетки.`, `Линий каждого направления 9.`],
        sol: `Две вертикальные линии из 9 выбираем ${C('9', '2')} = 36 способами, две горизонтальные — тоже 36. Всего 36 · 36 = 1296.` },
      { id: 'cnt-21', lvl: 3, r: 1430, type: 'num', q: `Сколько разных «слов» можно получить, переставляя буквы слова КОЛОКОЛ?`, a: ['210'],
        hints: [`К — 2 раза, О — 3 раза, Л — 2 раза.`],
        sol: `${fr('7!', '2! · 3! · 2!')} = ${fr('5040', '24')} = 210.` },
      { id: 'cnt-22', lvl: 3, r: 1460, type: 'num', q: `Сколькими способами 6 человек можно разбить на 3 пары? Пары не нумеруются.`, a: ['15'],
        hints: [`Возьми одного человека: для него 5 вариантов партнёра.`, `Затем возьми любого из оставшихся четырёх.`],
        sol: `Партнёра для Ани выбираем 5 способами. Из оставшихся четверых возьмём любого — для него 3 варианта партнёра. Последние двое образуют пару. 5 · 3 · 1 = 15.` },
      { id: 'cnt-23', lvl: 3, r: 1490, type: 'num', q: `Сколько существует четырёхзначных чисел, цифры которых строго возрастают слева направо (например, 1358)?`, a: ['126'],
        hints: [`Может ли в таком числе быть ноль?`, `Числу соответствует набор из 4 различных цифр от 1 до 9, и наоборот.`],
        sol: `Ноль не может стоять первым, а на любом другом месте он был бы меньше первой цифры. Значит, нуля нет. Любые 4 различные цифры от 1 до 9 записываются по возрастанию единственным образом. Поэтому чисел ${C('9', '4')} = 126.` },
      { id: 'cnt-24', lvl: 3, r: 1520, type: 'num', q: `На одной прямой отмечено 5 точек, а на параллельной ей прямой — 4 точки. Сколько существует треугольников с вершинами в отмеченных точках?`, a: ['70'],
        hints: [`У треугольника две вершины на одной прямой и одна — на другой.`],
        sol: `Две вершины на первой прямой и одна на второй: ${C('5', '2')} · 4 = 40. Одна на первой и две на второй: 5 · ${C('4', '2')} = 30. Всего 70. Иначе: ${C('9', '3')} − ${C('5', '3')} − ${C('4', '3')} = 84 − 10 − 4 = 70 — из всех троек вычитаем тройки на одной прямой.` },
      { id: 'cnt-25', lvl: 3, r: 1550, type: 'num', q: `Сколькими способами можно выбрать три различных числа из 1, 2, …, 20 так, чтобы их сумма была чётной?`, a: ['570'],
        hints: [`Чётных и нечётных чисел по 10.`, `Сумма трёх чисел чётна, если все три чётные или ровно одно чётное.`],
        sol: `Три чётных: ${C('10', '3')} = 120. Одно чётное и два нечётных: 10 · ${C('10', '2')} = 450. Всего 570.` },
      { id: 'cnt-26', lvl: 3, r: 1580, type: 'num', q: `Сколькими способами можно поставить в ряд 5 мальчиков и 5 девочек так, чтобы никакие два мальчика не стояли рядом?`, a: ['86400'],
        hints: [`Сначала расставь девочек. Между ними и по краям образуется 6 мест.`, `Мальчиков ставим в 5 разных мест из 6, по одному.`],
        sol: `Девочек расставляем 5! = 120 способами. Образуется 6 промежутков (4 между девочками и 2 по краям), в каждый можно поставить не больше одного мальчика. Упорядоченно разместить 5 мальчиков по 6 местам: 6 · 5 · 4 · 3 · 2 = 720. Ответ: 120 · 720 = 86400.` },
      { id: 'cnt-27', lvl: 3, r: 1610, type: 'num', q: `Двигаясь только вправо или вверх по линиям сетки, нужно пройти из левого нижнего угла квадрата 4 × 4 клетки в правый верхний, не проходя через центр квадрата. Сколько существует таких путей?`, a: ['34'],
        hints: [`Посчитай все пути и пути через центр.`, `Путь через центр — это путь до центра и путь от центра.`],
        sol: `Всех путей ${C('8', '4')} = 70. До центра ведут ${C('4', '2')} = 6 путей, от центра до конца — тоже 6, через центр проходят 6 · 6 = 36. Ответ: 70 − 36 = 34.` },
      { id: 'cnt-28', lvl: 3, r: 1640, type: 'num', q: `Сколько существует шестизначных чисел с нечётной суммой цифр?`, a: ['450000'],
        hints: [`Зафиксируй первые пять цифр. Сколько вариантов последней цифры дают нечётную сумму?`],
        sol: `При любых первых пяти цифрах ровно 5 из 10 вариантов последней цифры дают нечётную сумму. Шестизначных чисел 900000, ответ — ровно половина: 450000.` },

      // ── Уровень 4 · Финал ──
      { id: 'cnt-29', lvl: 4, r: 1680, type: 'num', q: `Сколько существует подмножеств множества {1, 2, …, 10}, не содержащих двух соседних чисел? Пустое множество тоже считается.`, a: ['144'],
        hints: [`Пусть f(n) — ответ для множества {1, …, n}. Входит ли n в подмножество?`, `Если n входит, то n − 1 не входит: f(n) = f(n − 1) + f(n − 2).`],
        sol: `Если n не входит, остаётся подмножество {1, …, n − 1} — f(n − 1) способов. Если входит, то n − 1 не входит, и остальное — подмножество {1, …, n − 2}: f(n − 2) способов. f(1) = 2 (пустое и {1}), f(2) = 3, дальше 5, 8, 13, 21, 34, 55, 89, 144. Ответ: f(10) = 144.` },
      { id: 'cnt-30', lvl: 4, r: 1720, type: 'proof', q: `Докажите, что у множества из n ≥ 1 элементов подмножеств с чётным числом элементов столько же, сколько с нечётным.`,
        hints: [`Возьми один элемент a. Что будет, если в каждом подмножестве «переключить» a: добавить, если его нет, и убрать, если он есть?`, `Чётность размера при этом меняется.`],
        sol: `Зафиксируем элемент a. Каждому подмножеству X сопоставим X′, полученное «переключением» a: если a ∈ X, уберём его, иначе добавим. Размер меняется на 1, поэтому чётное подмножество переходит в нечётное, и наоборот. Применив переключение дважды, вернёмся к X, поэтому это биекция между чётными и нечётными подмножествами. Значит, их поровну — по 2<sup>n−1</sup>.`,
        rubric: [[2, `Построено отображение «переключение элемента a»`], [2, `Показано, что оно меняет чётность размера`], [2, `Обосновано, что это биекция (обратное — то же переключение)`], [1, `Вывод`]] },
      { id: 'cnt-31', lvl: 4, r: 1760, type: 'num', q: `Сколькими способами можно выбрать три числа из 1, 2, …, 20, образующие арифметическую прогрессию? Порядок выбранных чисел не важен.`, a: ['90'],
        hints: [`Прогрессия a < b < c определяется крайними числами: b = (a + c)/2.`, `Числа a и c должны быть одной чётности.`],
        sol: `Тройка a < b < c — прогрессия, если b = ${fr('a + c', '2')}. Значит, тройка однозначно задаётся парой a < c одной чётности. Обратно, из любой такой пары получается прогрессия: середина — целое число между ними. Пар из двух чётных чисел ${C('10', '2')} = 45, из двух нечётных — тоже 45. Ответ: 90.` },
      { id: 'cnt-32', lvl: 4, r: 1800, type: 'proof', q: `Докажите, что при любом натуральном n число <span class="nw">${fr('(2n)!', '2<sup>n</sup> · n!')}</span> целое.`,
        hints: [`Найди, что считает это число.`, `Сколькими способами 2n человек можно разбить на n пар?`],
        sol: `Посчитаем число способов разбить 2n человек на n пар. Расставим их в ряд (2n)! способами и объединим в пары первого со вторым, третьего с четвёртым и так далее. Каждое разбиение на пары получается при этом ровно 2<sup>n</sup> · n! раз: сами пары можно переставить n! способами, а внутри каждой пары поменять людей местами — 2<sup>n</sup> способов. Значит, разбиений ${fr('(2n)!', '2<sup>n</sup> · n!')}, а число разбиений — целое. (Это число равно 1 · 3 · 5 · … · (2n − 1).)`,
        rubric: [[2, `Найден смысл: число разбиений 2n человек на пары`], [3, `Обосновано, что каждое разбиение посчитано ровно 2<sup>n</sup> · n! раз`], [2, `Вывод: частное равно числу разбиений и потому целое`]] },
      { id: 'cnt-33', lvl: 4, r: 1840, type: 'num', q: `На окружности отмечено 10 точек, и проведены все хорды с концами в этих точках. Никакие три хорды не пересекаются в одной точке внутри круга. Сколько точек пересечения хорд лежит внутри круга?`, a: ['210'],
        hints: [`Две хорды пересекаются внутри круга, если их концы чередуются на окружности.`, `Каждой точке пересечения соответствует четвёрка отмеченных точек, и наоборот.`],
        sol: `Каждая точка пересечения — это пересечение двух хорд с четырьмя различными концами, которые чередуются на окружности. Наоборот, любые 4 отмеченные точки ABCD (по порядку на окружности) дают ровно одну точку пересечения — диагоналей AC и BD четырёхугольника. Это биекция между точками пересечения и четвёрками точек: ${C('10', '4')} = 210.` },
      { id: 'cnt-34', lvl: 4, r: 1880, type: 'proof', q: `Докажите, что (${C('n', '0')})<sup>2</sup> + (${C('n', '1')})<sup>2</sup> + … + (${C('n', 'n')})<sup>2</sup> = ${C('2n', 'n')}.`,
        hints: [`Правая часть — число способов выбрать n человек из группы, где n мальчиков и n девочек.`, `Пусть выбрано k мальчиков. Сколько тогда девочек?`, `${C('n', 'n − k')} = ${C('n', 'k')}.`],
        sol: `В группе n мальчиков и n девочек. Выбрать из неё n человек можно ${C('2n', 'n')} способами. Посчитаем иначе: если выбрано k мальчиков (${C('n', 'k')} способов), то девочек выбрано n − k (${C('n', 'n − k')} = ${C('n', 'k')} способов). Для каждого k получаем (${C('n', 'k')})<sup>2</sup> способов, а сумма по k от 0 до n — все выборы. Тождество доказано.`,
        rubric: [[2, `Правая часть истолкована как выбор n человек из 2n`], [3, `Разбор по числу k выбранных мальчиков: ${C('n', 'k')} · ${C('n', 'n − k')}`], [2, `Использовано ${C('n', 'n − k')} = ${C('n', 'k')}, вывод`]] },
      { id: 'cnt-35', lvl: 4, r: 1920, type: 'num', q: `Сколько существует перестановок чисел 1, 2, …, 10, в которых каждое число, кроме первого, отличается на 1 хотя бы от одного из чисел, стоящих левее него?`, a: ['512'],
        hints: [`Числа на первых k местах всегда образуют набор подряд идущих чисел.`, `Каждое следующее число — либо на 1 меньше наименьшего, либо на 1 больше наибольшего из уже выписанных.`, `Перестановка определяется тем, на каких шагах мы шли «вниз».`],
        sol: `По индукции первые k чисел образуют набор подряд идущих чисел {m, …, M}: новое число отличается на 1 от одного из них и не совпадает ни с одним, поэтому оно равно m − 1 или M + 1. Значит, после первого числа на каждом из 9 шагов выбираем «вниз» или «вверх». Шагов вниз ровно (первое число − 1), поэтому перестановка однозначно задаётся множеством шагов, на которых шли вниз, и любое подмножество из 9 шагов подходит (первое число тогда равно числу шагов вниз плюс 1). Ответ: 2<sup>9</sup> = 512.` },
      { id: 'cnt-36', lvl: 4, r: 1950, type: 'proof', q: `Докажите, что ${C('n', 'n')} + ${C('n + 1', 'n')} + ${C('n + 2', 'n')} + … + ${C('m', 'n')} = ${C('m + 1', 'n + 1')} при m ≥ n.`,
        hints: [`Правая часть — число (n + 1)-элементных подмножеств множества {1, 2, …, m + 1}.`, `Разбей эти подмножества по наибольшему элементу.`],
        sol: `Посчитаем (n + 1)-элементные подмножества множества {1, …, m + 1}, разбив их по наибольшему элементу. Если наибольший элемент равен j + 1, то остальные n элементов выбираются из {1, …, j}: ${C('j', 'n')} способов. Наибольший элемент не меньше n + 1, поэтому j меняется от n до m. Сумма ${C('n', 'n')} + … + ${C('m', 'n')} учитывает каждое подмножество ровно один раз, то есть равна ${C('m + 1', 'n + 1')}. (На треугольнике Паскаля эта сумма выглядит как клюшка, поэтому тождество называют «хоккейной клюшкой».)`,
        rubric: [[2, `Правая часть истолкована как число (n + 1)-элементных подмножеств`], [3, `Разбиение по наибольшему элементу и подсчёт ${C('j', 'n')}`], [2, `Проверены границы суммы, вывод`]] },

      // ── Уровень 5 · Международный ──
      { id: 'cnt-37', lvl: 5, r: 2060, type: 'num', q: `Полоску 1 × 10 разрезают по линиям сетки на несколько частей (можно не разрезать вовсе), после чего каждую часть целиком красят в белый или чёрный цвет. Результат — это набор разрезов вместе с раскраской частей. Сколько существует различных результатов?`, a: ['39366'],
        hints: [`Обходи клетки слева направо и для каждой из 9 внутренних линий решай, режем ли по ней.`, `Для каждой следующей клетки три варианта: разрез и белый цвет, разрез и чёрный цвет, или без разреза (тогда цвет тот же).`],
        sol: `Первую клетку красим 2 способами. Для каждой следующей клетки ровно 3 варианта: перед ней разрез, и она белая; разрез, и она чёрная; разреза нет, и она того же цвета, что предыдущая. Каждый результат получается ровно одним способом. Ответ: 2 · 3<sup>9</sup> = 39366.` },
      { id: 'cnt-38', lvl: 5, r: 2150, type: 'proof', q: `Рассмотрим все строки длины n ≥ 2 из нулей и единиц. Докажите, что ровно в половине из них пара «01» встречается столько же раз, сколько пара «10» (считаются пары соседних символов).`,
        hints: [`Разбей строку на блоки одинаковых символов. Как чередуются переходы «01» и «10»?`, `Переходы чередуются, поэтому их количества отличаются не больше чем на 1.`, `Количества равны тогда и только тогда, когда первый и последний символы совпадают.`],
        sol: `Пары «01» и «10» — это переходы между соседними блоками одинаковых символов, и они чередуются: после перехода 0 → 1 следующий переход обязательно 1 → 0, и наоборот. Поэтому их количества отличаются не больше чем на 1 и равны ровно тогда, когда переходов чётное число, то есть когда строка начинается и заканчивается одним и тем же символом. Таких строк 2 · 2<sup>n−2</sup> = 2<sup>n−1</sup>: первый символ любой, середина любая, последний равен первому. Это ровно половина от 2<sup>n</sup>.`,
        rubric: [[3, `Переходы «01» и «10» чередуются, их количества отличаются не более чем на 1`], [2, `Равенство ⇔ первый символ равен последнему`], [2, `Подсчёт: 2<sup>n−1</sup> строк, то есть половина`]] },
      { id: 'cnt-39', lvl: 5, r: 2240, type: 'num', q: `Клетки полоски 1 × 10 красят в 3 цвета так, чтобы соседние клетки были разного цвета, а первая и последняя клетки — тоже разного цвета. Сколько существует таких раскрасок?`, a: ['1026'],
        hints: [`Пусть a<sub>n</sub> — число раскрасок полоски 1 × n, где соседние клетки разного цвета и первая с последней разного цвета, а b<sub>n</sub> — где соседние разного цвета, а первая и последняя одного.`, `a<sub>n</sub> + b<sub>n</sub> = 3 · 2<sup>n−1</sup>.`, `b<sub>n</sub> = a<sub>n−1</sub>: отбрось последнюю клетку.`],
        sol: `Раскрасок с разными цветами соседних клеток 3 · 2<sup>n−1</sup>; из них a<sub>n</sub> имеют разные цвета у первой и последней клетки, b<sub>n</sub> — одинаковые. Если первая и последняя клетки одного цвета, то предпоследняя отличается от последней, то есть и от первой. Отбросив последнюю клетку, получим раскраску, учтённую в a<sub>n−1</sub>, и наоборот. Значит, b<sub>n</sub> = a<sub>n−1</sub> и a<sub>n</sub> = 3 · 2<sup>n−1</sup> − a<sub>n−1</sub>. Отсюда a<sub>2</sub> = 6, a<sub>3</sub> = 6, a<sub>4</sub> = 18, a<sub>5</sub> = 30, a<sub>6</sub> = 66, a<sub>7</sub> = 126, a<sub>8</sub> = 258, a<sub>9</sub> = 510, a<sub>10</sub> = 1536 − 510 = 1026.` },
      { id: 'cnt-40', lvl: 5, r: 2350, type: 'proof', q: `Пусть a<sub>n</sub> — количество способов замостить полоску 1 × n плитками 1 × 1 и 1 × 2. Докажите, что a<sub>n</sub> = a<sub>n−1</sub> + a<sub>n−2</sub> и что a<sub>n</sub> = ${C('n', '0')} + ${C('n − 1', '1')} + ${C('n − 2', '2')} + … (суммирование идёт, пока нижний индекс не больше верхнего).`,
        hints: [`Для рекуррентной формулы посмотри на последнюю плитку.`, `Пусть в замощении k плиток 1 × 2. Сколько всего плиток?`, `Плиток n − k; замощение определяется тем, какие k из них длинные.`],
        sol: `Последняя плитка — либо 1 × 1 (перед ней замощение длины n − 1), либо 1 × 2 (перед ней замощение длины n − 2). Отсюда a<sub>n</sub> = a<sub>n−1</sub> + a<sub>n−2</sub>.<br>Для второй формулы: если в замощении k плиток 1 × 2, то плиток 1 × 1 будет n − 2k, а всего плиток n − k. Замощение однозначно задаётся тем, какие k из n − k плиток (по порядку слева направо) длинные: ${C('n − k', 'k')} способов. Суммируя по k = 0, 1, 2, … , пока 2k ≤ n, получаем формулу.`,
        rubric: [[3, `Рекуррентная формула по последней плитке`], [3, `Подсчёт ${C('n − k', 'k')} замощений с k длинными плитками`], [1, `Суммирование по k, вывод`]] }
    ]
  });
})();

